// src/components/AgentAudio.jsx
import React, { useEffect, useRef, useState } from "react";

// tiny UUID4 for session IDs
function uuid4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    return ((c === "x" ? r : (r & 0x3) | 0x8)).toString(16);
  });
}

export default function AgentAudio() {
  const wsRef            = useRef(null);
  const audioCtxRef      = useRef(null);
  const bufferRef        = useRef([]);
  const sendQueueRef     = useRef([]);
  const lastAudioTimeRef = useRef(0);
  const totalSentRef     = useRef(0);

  const [listening, setListening]     = useState(false);
  const [limitReached, setLimitReached] = useState(false);

  // generate once
  const appName   = "portfolio-agent";
  const userIdRef = useRef(`u_${uuid4()}`);
  const sessionIdRef = useRef(`s_${uuid4()}`);
  const userId = userIdRef.current;
  const sessionId = sessionIdRef.current;
  const serverBase= "https://portfolio-agent-82950855182.asia-south1.run.app";
  // const serverBase= "http://127.0.0.1:8000";

  // decode URL‑safe base64
  const urlSafeBase64ToUint8 = b64 => {
    let s = b64.replace(/_/g,"/").replace(/-/g,"+");
    while (s.length % 4) s += "=";
    const bin = atob(s), u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return u8;
  };

  // play 16‑bit PCM LE at 22kHz
  const playPCM = pcmBytes => {
    const samples = pcmBytes.length / 2;
    const f32 = new Float32Array(samples);
    for (let i = 0; i < samples; i++) {
      let v = pcmBytes[i*2] | (pcmBytes[i*2+1] << 8);
      if (v >= 32768) v -= 65536;
      f32[i] = v / 32768;
    }
    const ctx = audioCtxRef.current;
    if (ctx.state === "suspended") ctx.resume();
    const buf = ctx.createBuffer(1, samples, 22000);
    buf.copyToChannel(f32, 0);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.connect(ctx.destination);
    const now = ctx.currentTime;
    const start = Math.max(lastAudioTimeRef.current, now);
    src.start(start);
    lastAudioTimeRef.current = start + buf.duration;
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps -- userId and sessionId are stable refs
  useEffect(() => {
    let playInterval, sendInterval;

    // 1️⃣ create session
    fetch(`${serverBase}/apps/${appName}/users/${userId}/sessions/${sessionId}`, {
      method: "POST",
      headers: {"Content-Type":"application/json"},
      body: JSON.stringify({state:{}})
    })
    .then(res => {
      if (!res.ok) throw new Error("Session creation failed");

      // 2️⃣ setup WebSocket & AudioContext
      audioCtxRef.current = new AudioContext({sampleRate:22000});
      const wsUrl = serverBase.replace(/^http/, "ws") +
        `/run_live?app_name=${appName}` +
        `&user_id=${userId}` +
        `&session_id=${sessionId}` +
        `&modalities=AUDIO`;
      const ws = new WebSocket(wsUrl);
      ws.binaryType = "arraybuffer";
      wsRef.current = ws;

      ws.onopen = async () => {
        setListening(true);
        ws.send(JSON.stringify({content:{parts:[{text:"START"}]},close:false}));
        ws.send(JSON.stringify({blob:{data:"",mimeType:"audio/pcm"},close:false}));

        bufferRef.current = [];
        lastAudioTimeRef.current = 0;
        playInterval = setInterval(() => {
          if (!bufferRef.current.length) return;
          const total = bufferRef.current.reduce((s,a)=>s+a.length,0);
          const merged = new Uint8Array(total);
          let off=0;
          for (let chunk of bufferRef.current) {
            merged.set(chunk, off);
            off += chunk.length;
          }
          bufferRef.current = [];
          playPCM(merged);
        }, 250);

        const ctx = audioCtxRef.current;
        await ctx.audioWorklet.addModule("/audio-processor.js");
        const stream = await navigator.mediaDevices.getUserMedia({audio:true});
        const micSrc = ctx.createMediaStreamSource(stream);
        const worklet = new AudioWorkletNode(ctx, "audio-processor");
        micSrc.connect(worklet);

        worklet.port.onmessage = e => {
          const f32 = e.data;
          const i16 = new Int16Array(f32.length);
          for (let i=0; i<f32.length; i++){
            i16[i] = Math.max(-1,Math.min(1,f32[i]))*0x7fff;
          }
          sendQueueRef.current.push(i16);
        };

        sendInterval = setInterval(() => {
          if (limitReached) return;
          const Q = sendQueueRef.current.splice(0);
          if (!Q.length) return;
          const allowed=[];
          for (let ch of Q) {
            const secs = ch.length/22000;
            if (totalSentRef.current+secs > 180) {
              setLimitReached(true);
              break;
            }
            totalSentRef.current += secs;
            allowed.push(ch);
          }
          if (!allowed.length) return;
          const tot = allowed.reduce((s,a)=>s+a.length,0);
          const buf = new Int16Array(tot);
          let o=0;
          for (let ch of allowed){
            buf.set(ch,o);
            o+=ch.length;
          }
          const b64 = btoa(String.fromCharCode(...new Uint8Array(buf.buffer)));
          ws.send(JSON.stringify({blob:{mimeType:"audio/pcm",data:b64},close:false}));
        },200);
      };

      ws.onmessage = ({data})=>{
        try {
          const msg = JSON.parse(data);
          const inline = msg.content?.parts?.[0]?.inlineData;
          if (!inline) return;
          bufferRef.current.push(urlSafeBase64ToUint8(inline.data));
        } catch {}
      };
      ws.onclose = ws.onerror = () => setListening(false);

    })
    .catch(console.error);

    return () => {
      clearInterval(playInterval);
      clearInterval(sendInterval);
      wsRef.current?.close();
      audioCtxRef.current?.close();
    };
  }, [limitReached, userId, sessionId]);

  return (
    <div style={{ padding:"16px 12px", textAlign:"center" }}>
      <div style={{
        display:"inline-flex",
        alignItems:"center",
        gap:8,
        padding:"8px 16px",
        background:"rgba(255,255,255,0.1)",
        borderRadius:20,
        marginBottom:8,
      }}>
        <span style={{
          width:10, height:10, borderRadius:"50%", display:"inline-block",
          background:listening?"#22c55e":"#888"
        }} />
        <span style={{ color:"#fff", fontSize:14 }}>
          {listening ? "Listening…" : "Connecting..."}
        </span>
      </div>
      {limitReached && (
        <div style={{
          marginTop:8, padding:"8px 12px",
          background:"rgba(239,68,68,0.15)",
          border:"1px solid rgba(239,68,68,0.4)",
          borderRadius:6, color:"#fca5a5", fontSize:13,
        }}>
          Audio session limit (180 s) reached.
        </div>
      )}
    </div>
  );
}
