import React from "react";

function ProjectCards({ imgPath, embedUrl, title, description, ghLink, demoLink, tags }) {
  const linkHref = demoLink || ghLink;
  const linkLabel = demoLink ? "View Demo →" : ghLink ? "GitHub →" : null;

  return (
    <div className="project-card-new">
      <div className="project-card-img">
        {embedUrl ? (
          <iframe
            src={embedUrl}
            frameBorder="0"
            allowFullScreen
            title={title}
            style={{ width: "100%", height: "400px", border: "none", display: "block" }}
          />
        ) : (
          imgPath && <img src={imgPath} alt={title} />
        )}
      </div>
      <div className="project-card-body">
        {tags && tags.length > 0 && (
          <div className="project-card-tags">
            {tags.map((tag) => (
              <span key={tag} className="project-card-tag">
                {tag}
              </span>
            ))}
          </div>
        )}
        <div className="project-card-title">{title}</div>
        <div className="project-card-desc">{description}</div>
        {linkHref && (
          <a
            href={linkHref}
            target="_blank"
            rel="noreferrer"
            className="project-card-link"
          >
            {linkLabel}
          </a>
        )}
      </div>
    </div>
  );
}

export default ProjectCards;
