import React, { useState, useEffect } from "react";
import LiveAudioAgent from "../AgentAudio.jsx";

function AgentFab() {
  const [agentOpen, setAgentOpen] = useState(false);
  const [pulseVisible, setPulseVisible] = useState(true);
  const [showTooltip, setShowTooltip] = useState(false);
  const [agentActive, setAgentActive] = useState(false);

  useEffect(() => {
    const t = setTimeout(() => setPulseVisible(false), 8000);
    return () => clearTimeout(t);
  }, []);

  function handleFabClick() {
    setAgentOpen((v) => !v);
    setPulseVisible(false);
  }

  return (
    <>
      {/* Slide-up panel */}
      <div className={`agent-panel${agentOpen ? " agent-panel--open" : ""}`}>
        <div className="agent-panel__header">
          <div className="agent-panel__avatar-circle">
            <svg viewBox="0 0 24 24" fill="currentColor" width="22" height="22" aria-hidden="true">
              <rect x="5" y="8" width="14" height="10" rx="2"/>
              <rect x="9" y="4" width="6" height="4" rx="1"/>
              <rect x="11" y="2" width="2" height="2" rx="1"/>
              <circle cx="9" cy="13" r="1.5"/>
              <circle cx="15" cy="13" r="1.5"/>
              <rect x="9" y="15.5" width="6" height="1.5" rx="0.75"/>
              <rect x="3" y="10" width="2" height="4" rx="1"/>
              <rect x="19" y="10" width="2" height="4" rx="1"/>
            </svg>
          </div>
          <div>
            <div className="agent-panel__name">Kamal's AI Agent</div>
            <div className="agent-panel__status">
              <span className="agent-panel__online-dot" />
              Online · Powered by Google ADK
            </div>
          </div>
          <button
            className="agent-panel__close"
            onClick={() => { setAgentOpen(false); setAgentActive(false); }}
            aria-label="Close agent panel"
          >
            ✕
          </button>
        </div>

        <div className="agent-panel__body">
          {agentActive ? (
            <LiveAudioAgent />
          ) : (
            <>
              <div className="agent-panel__bubble">
                Hi! I'm Kamal's AI portfolio agent. Ask me anything about his
                experience, projects, or skills!
              </div>
              <div className="agent-panel__suggestions">
                <button className="agent-panel__suggestion">
                  What's your experience with GenAI?
                </button>
                <button className="agent-panel__suggestion">
                  Tell me about your hackathon wins
                </button>
                <button className="agent-panel__suggestion">
                  What's the AI Voice Agent project?
                </button>
              </div>
            </>
          )}
        </div>

        {!agentActive && (
          <div className="agent-panel__footer">
            <button
              className="agent-panel__mic-btn"
              onClick={() => setAgentActive(true)}
              aria-label="Start voice conversation"
            >
              🎤
            </button>
            <span className="agent-panel__hint">
              Click mic to start a voice conversation
            </span>
          </div>
        )}
      </div>

      {/* FAB */}
      <div className="agent-fab-wrapper">
        {pulseVisible && (
          <>
            <div className="agent-fab__ring agent-fab__ring--1" />
            <div className="agent-fab__ring agent-fab__ring--2" />
          </>
        )}
        <button
          className="agent-fab"
          onClick={handleFabClick}
          onMouseEnter={() => setShowTooltip(true)}
          onMouseLeave={() => setShowTooltip(false)}
          aria-label="Toggle AI Agent"
        >
          🎤
        </button>
        {showTooltip && !agentOpen && (
          <div className="agent-fab__tooltip">Talk to my portfolio agent!</div>
        )}
      </div>
    </>
  );
}

export default AgentFab;
