import React from "react";
import Typewriter from "typewriter-effect";

function Type() {
  return (
    <Typewriter
      onInit={(typewriter) => {
        typewriter
          .typeString("Gen AI Engineer")
          .pauseFor(1600)
          .deleteAll(40)
          .typeString("Cloud Architect")
          .pauseFor(1600)
          .deleteAll(40)
          .typeString("Python Developer")
          .pauseFor(1600)
          .deleteAll(40)
          .typeString("Chatbot Builder")
          .pauseFor(1600)
          .deleteAll(40)
          .typeString("Agentic AI Builder")
          .pauseFor(1600)
          .deleteAll(40)
          .start();
      }}
      options={{
        delay: 80,
        deleteSpeed: 40,
        loop: true,
      }}
    />
  );
}

export default Type;
