import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
  const [expand, setExpand] = useState(false);
  const [navColour, setNavColour] = useState(false);

  function scrollHandler() {
    if (window.scrollY >= 20) {
      setNavColour(true);
    } else {
      setNavColour(false);
    }
  }
  window.addEventListener("scroll", scrollHandler);

  return (
    <nav className={`navbar${navColour ? " sticky" : ""}`}>
      <Link to="/" className="navbar-brand" onClick={() => setExpand(false)}>
        kamal<span className="logo-dot">.</span>
      </Link>

      {/* Mobile toggle */}
      <button
        className={`navbar-toggler${expand ? "" : " collapsed"}`}
        onClick={() => setExpand((v) => !v)}
        aria-label="Toggle navigation"
      >
        <span />
        <span />
        <span />
      </button>

      <div
        className={`navbar-collapse${expand ? " nav-open" : ""}`}
      >
        <ul className="navbar-nav ms-auto">
          <li className="nav-item">
            <Link
              to="/about"
              className="nav-link"
              onClick={() => setExpand(false)}
            >
              About
            </Link>
          </li>
          <li className="nav-item">
            <Link
              to="/project"
              className="nav-link"
              onClick={() => setExpand(false)}
            >
              Projects
            </Link>
          </li>
          <li className="nav-item" style={{ marginLeft: "8px" }}>
            <Link
              to="/resume"
              className="nav-resume-btn"
              onClick={() => setExpand(false)}
            >
              Resume →
            </Link>
          </li>
        </ul>
      </div>
    </nav>
  );
}

export default NavBar;
