import React, { useRef, useState, useEffect } from "react";

export default function AudioPlayerWithTranscript({
  audioSrc = "/audio.wav",
  vttSrc = "/audio.vtt",
}) {
  const audioRef = useRef();
  const transcriptRef = useRef();
  const [cues, setCues] = useState([]);
  const [currentIdx, setCurrentIdx] = useState(-1);

  // once VTT is parsed by the browser, grab cues & listen for cue changes
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const onLoaded = () => {
      const track = audio.textTracks[0];
      track.mode = "hidden";
      const arr = Array.from(track.cues).map((c) => ({
        start: c.startTime,
        text: c.text,
        cue: c,
      }));
      setCues(arr);

      track.addEventListener("cuechange", () => {
        const active = Array.from(track.activeCues);
        if (active.length) {
          const idx = arr.findIndex((x) => x.cue === active[0]);
          setCurrentIdx(idx);
        } else {
          setCurrentIdx(-1);
        }
      });
    };

    audio.addEventListener("loadedmetadata", onLoaded);
    return () => audio.removeEventListener("loadedmetadata", onLoaded);
  }, []);

  // keep the active line centered
  useEffect(() => {
    if (currentIdx < 0) return;
    const el = transcriptRef.current.children[currentIdx];
    if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
  }, [currentIdx]);

  const jumpTo = (t) => {
    audioRef.current.currentTime = t;
    audioRef.current.play();
  };

  // theme colors
  const bgDark = "#1f0e3a";
  const fgLight = "#eee";
  const accent = "rgba(109,32,197,0.3)"; // light purple
  const accentHover = "rgba(109,32,197,0.1)";

  return (
    <div
      style={{
        display: "flex",
        gap: 24,
        maxWidth: 900,
        margin: "40px auto",
        padding: 0,
        flexDirection: window.innerWidth <= 600 ? "column" : "row",
      }}
    >
      {/* Left: Audio + Transcript */}
      <div style={{ flex: 2, minWidth: 0, marginBottom: window.innerWidth <= 600 ? 24 : 0 }}>
        <audio
          ref={audioRef}
          src={audioSrc}
          controls
          style={{
            width: "100%",
            borderRadius: 12,
            boxShadow: "0 4px 16px rgba(0,0,0,0.1)",
            background: bgDark,
            marginBottom: 16,
          }}
        >
          <track kind="captions" src={vttSrc} default />
        </audio>
        <div
          ref={transcriptRef}
          style={{
            maxHeight: 220,
            overflowY: "auto",
            background: bgDark,
            color: fgLight,
            borderRadius: 12,
            boxShadow: "0 4px 16px rgba(0,0,0,0.1)",
            padding: window.innerWidth <= 600 ? 10 : 16,
            fontSize: window.innerWidth <= 600 ? 14 : 16,
          }}
        >
          {cues.map((c, i) => {
            const isActive = i === currentIdx;
            const cleanedText = c.text.replace(/\s*\d+\s*$/, "");
            return (
              <div
                key={i}
                onClick={() => jumpTo(c.start)}
                style={{
                  cursor: "pointer",
                  padding: window.innerWidth <= 600 ? "6px 8px" : "8px 12px",
                  margin: "4px 0",
                  borderRadius: 8,
                  background: isActive ? accent : "transparent",
                  color: fgLight,
                  fontWeight: isActive ? 600 : 400,
                  transition: "background 0.2s",
                  fontSize: window.innerWidth <= 600 ? 14 : 16,
                }}
                onMouseOver={(e) => {
                  if (!isActive) e.currentTarget.style.background = accentHover;
                }}
                onMouseOut={(e) => {
                  if (!isActive) e.currentTarget.style.background = "transparent";
                }}
              >
                {cleanedText}
              </div>
            );
          })}
        </div>
      </div>
      {/* Right: Info Panel */}
      <div
        style={{
          flex: 1,
          background: bgDark,
          color: fgLight,
          borderRadius: 12,
          boxShadow: "0 4px 16px rgba(0,0,0,0.1)",
          padding: window.innerWidth <= 600 ? 16 : 24,
          fontFamily: "'Inter', sans-serif",
          lineHeight: 1.5,
          fontSize: window.innerWidth <= 600 ? 14 : 16,
        }}
      >
        <h3 style={{ marginTop: 0, marginBottom: 12, color: "#d1b3ff", fontSize: window.innerWidth <= 600 ? 18 : 22 }}>
          About this Audio
        </h3>
        <p style={{ marginBottom: 16 }}>
          Created with <strong>NotebookLM</strong>, this audio showcases my curiosity
          and commitment to leveraging the latest AI tools for continuous learning
          and growth.
        </p>
        <p>
          <strong>Podcast format:</strong> Two Speakers discuss my skills and
          experiences, offering a conversational insight into my professional journey.
        </p>
      </div>
    </div>
  );
}
